import React, { useEffect, useState } from "react";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import { IconButton } from "@mui/material";
import { useNavigate, useLocation } from "react-router-dom";
import ArrowDropDownIcon from "@mui/icons-material/ArrowDropDown";
import http from "../../services/utility";
import { apisPath } from "../../utils/path";
import SearchIcon from "@mui/icons-material/Search";
import MenuItem from "@mui/material/MenuItem";
import FormControl from "@mui/material/FormControl";
import Select from "@mui/material/Select";
import { useDispatch } from "react-redux";
import { openSuccessTicker } from "../../redux/reducer/SuccessTickerReducer";
import { openTicker } from "../../redux/reducer/ErrorTickerReducer";

export default function AddNewDeals() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { state } = useLocation();

  const [dealData, setDealData] = useState(state?.dealData);
  const [updateMode, setUpdateMode] = useState(state?.updateMode);

  const [dealType, setDealType] = useState("Single");
  const [categoryFilter, setCategoryFilter] = useState("category");
  const [subCategoryFilter, setSubCategoryFilter] = useState("sub_category");
  const [isForLimitedTime, setIsForLimitedTime] = useState(false);
  const [limitedTimeDate, setLimitedTimeDate] = useState(null);

  const [dealName, setDealName] = useState("");
  const [allProductOnceUpdated, setAllProductOnceUpdated] = useState(false);

  const [allProductList, setAllProductList] = useState([]);
  const [allComboList, setAllComboList] = useState([]);
  const [addedProduct, setAddedProduct] = useState([]);
  const [addedProductIds, setAddedProductIds] = useState([]);

  const [addedProductHeader, setAddedProductHeader] = useState([
    { name: "Product" },
    { name: "Price" },
    { name: "Expiry date" },
    { name: "Action" },
  ]);

  const [addedComboHeader, setComboHeader] = useState([
    { name: "Combo Image" },
    { name: "Combo Name" },
    { name: "Combo Created At" },
    { name: "Action" },
  ]);

  useEffect(() => {
    if (updateMode) {
      setDealName(dealData?.name);
      setDealType(dealData?.type);
      setIsForLimitedTime(dealData?.isForLimitedTime);

      if (dealData?.isForLimitedTime && dealData?.expireDateTime) {
        setLimitedTimeDate(dealData?.expireDateTime);
      }
      let ids = [];
      dealData?.products?.forEach((id) => {
        ids.push(id?.id);
      });
      setAddedProductIds(ids);
      setAddedProduct(dealData?.products);
    }
  }, [dealData]);

  useEffect(() => {
    if (allProductList.length && updateMode && !allProductOnceUpdated) {
      let updatedAllProduct = allProductList?.filter(
        (item) => !addedProductIds.includes(item?.id)
      );

      setAllProductList(updatedAllProduct);

      setAllProductOnceUpdated(true);
    }
  }, [allProductList]);

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    await http
      .get(apisPath?.admin?.productAllData)
      .then(async (res) => {
        // console.log(res?.data?.products);
        setAllProductList(res?.data?.products);
      })
      .catch((err) => {
        console.log(err);
      });

    await http
      .get(apisPath?.admin?.comboCategories)
      .then(async (res) => {
        // console.log(res?.data?.comboCategories);
        setAllComboList(res?.data?.comboCategories);
      })
      .catch((err) => {
        console.log(err);
      });
  };

  const addNewDeal = async () => {
    await http
      .post(apisPath?.admin?.deals, {
        name: dealName,
        type: dealType,
        isForLimitedTime: isForLimitedTime,
        expireDateTime: limitedTimeDate,
      })
      .then(async (res) => {
        // console.log(res?.data?.deal);
        let dealId = res?.data?.deal?.id;
        await http
          .put(`${apisPath?.admin?.deals}/${dealId}`, {
            products: addedProductIds,
          })
          .then(async (res) => {
            // console.log(res?.data?.deal);
            dispatch(
              openSuccessTicker({ title: "Success", body: res?.data?.message })
            );
            navigate(-1);
          })
          .catch((err) => {
            // console.log(err);
            dispatch(
              openTicker({ title: "Error", body: err?.response?.data?.message })
            );
          });
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const updateDeal = async () => {
    let dealId = dealData?.id;
    await http
      .put(`${apisPath?.admin?.deals}/${dealId}`, {
        products: addedProductIds,
      })
      .then(async (res) => {
        // console.log(res?.data?.deal);
        dispatch(
          openSuccessTicker({ title: "Success", body: res?.data?.message })
        );
        navigate(-1);
      })
      .catch((err) => {
        // console.log(err);
        dispatch(
          openTicker({ title: "Error", body: err?.response?.data?.message })
        );
      });
  };

  const handleCategoryChange = (event) => {
    setCategoryFilter(event?.target?.value);
  };

  const handleSubCategoryChange = (event) => {
    setSubCategoryFilter(event?.target?.value);
  };

  const handleDealTypeChange = async (event) => {
    await getData();
    setAddedProduct([]);
    setDealType(event?.target?.value);
  };

  return (
    <div className="add_new_deal">
      <div className="detail__header">
        <IconButton
          aria-label="Back"
          className="back__button"
          onClick={() => navigate(-1)}
        >
          <ArrowBackIcon />
        </IconButton>
        <h3 className="page_heading">Deals {">"} Add new deal</h3>
      </div>
      <div className="add_new_deal__content">
        <div className="add_new_deal__content__deal__title">
          <div className="add_new_deal__content__deal__title__input">
            <label htmlFor="deal_title">Deal type</label>
            <FormControl fullWidth>
              <Select
                value={dealType}
                onChange={handleDealTypeChange}
                disabled={updateMode}
              >
                <MenuItem value={"Single"}>Single</MenuItem>
                <MenuItem value={"Combo"}>Combo</MenuItem>
              </Select>
            </FormControl>
          </div>
          <div className="add_new_deal__content__deal__title__input">
            <label htmlFor="deal_title">Deal title</label>
            <input
              type="text"
              id="deal_title"
              placeholder="Enter here"
              value={dealName}
              onChange={(e) => setDealName(e?.target?.value)}
              disabled={updateMode}
            />
          </div>

          <div className="coupons__content__top_content__small_container__no_of_user">
            <label htmlFor="qty">
              Is for Limited Time?
              <label className="coupons__content__top_content__small_container__no_of_user__switch">
                <input
                  type="checkbox"
                  onChange={(e) => {
                    if (!updateMode) {
                      setIsForLimitedTime(e?.target?.checked);
                    }
                  }}
                />
                <span className="slider round"></span>
              </label>
            </label>
            {!isForLimitedTime ? (
              <input
                type="text"
                id="limitedTime"
                name="limitedTime"
                placeholder="Select the Date and Time"
                value={limitedTimeDate}
                disabled
              />
            ) : (
              <input
                type="datetime-local"
                id="limitedTime"
                name="limitedTime"
                placeholder="Select the Date and Time"
                value={limitedTimeDate}
                min={new Date().toISOString().slice(0, 16)}
                onChange={(e) => {
                  setLimitedTimeDate(e.target.value);
                }}
                disabled={updateMode}
              />
            )}
          </div>
        </div>

        <div className="add_new_deal__content__added_product">
          <h5 className="add_new_deal__content__added_product__heading page_subheading">
            {dealType == "Single" ? "Added products" : "Added Combos"}
          </h5>
          <div className="add_new_deal__content__added_product__content">
            <table className="deals__content__card_container__table__table">
              <tr>
                {dealType == "Single"
                  ? addedProductHeader?.map((header, index) => {
                      return (
                        <th key={index}>
                          <span>
                            {header?.name} <ArrowDropDownIcon />
                          </span>
                        </th>
                      );
                    })
                  : addedComboHeader?.map((header, index) => {
                      return (
                        <th key={index}>
                          <span>
                            {header?.name} <ArrowDropDownIcon />
                          </span>
                        </th>
                      );
                    })}
              </tr>
              {dealType == "Single"
                ? addedProduct?.map((data, index) => {
                    return (
                      <tr key={index}>
                        <td>
                          <div className="product div-flex">
                            <img src={data?.images[0]} alt="Product Image" />
                            <div className="product__info">
                              <span>{data?.name}</span>
                              <span>
                                Details:{" "}
                                {data?.details?.length > 0
                                  ? data?.details[0]?.body
                                  : ""}
                              </span>
                            </div>
                          </div>
                        </td>
                        <td>&#8377; {data?.varients[0]?.sellingPrice}</td>
                        {/* <td>{data?.purchased}</td>
                        <td>{data?.stock}</td> */}
                        <td>
                          {new Date(data?.createdAt)?.toLocaleString("en-US", {
                            weekday: "short",
                            year: "numeric",
                            month: "short",
                            day: "numeric",
                            timeZone: "UTC",
                          })}
                        </td>
                        <td>
                          <div className="product_action">
                            <button
                              className="button-red"
                              onClick={() => {
                                const updatedArray = [...allProductList, data];
                                setAllProductList(updatedArray);

                                const updatedArray1 = addedProduct?.filter(
                                  (item) => item?.id !== data?.id
                                );
                                setAddedProduct(updatedArray1);

                                const updatedArray2 = addedProductIds?.filter(
                                  (item) => item !== data?.id
                                );
                                setAddedProductIds(updatedArray2);
                              }}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                : addedProduct?.map((data, index) => {
                    return (
                      <tr key={index}>
                        <td>
                          <div className="product div-flex">
                            <img src={data?.image} alt="Product Image" />
                          </div>
                        </td>
                        <td>{data?.name}</td>
                        {/* <td>{data?.purchased}</td>
                    <td>{data?.stock}</td> */}
                        <td>
                          {new Date(data?.createdAt)?.toLocaleString("en-US", {
                            weekday: "short",
                            year: "numeric",
                            month: "short",
                            day: "numeric",
                            timeZone: "UTC",
                          })}
                        </td>
                        <td>
                          <div className="product_action">
                            <button
                              className="button-red"
                              onClick={() => {
                                const updatedArray = [...allComboList, data];
                                setAllComboList(updatedArray);

                                const updatedArray1 = addedProduct?.filter(
                                  (item) => item?.id !== data?.id
                                );
                                setAddedProduct(updatedArray1);

                                const updatedArray2 = addedProductIds?.filter(
                                  (item) => item !== data?.id
                                );
                                setAddedProductIds(updatedArray2);
                              }}
                            >
                              Delete
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
            </table>
          </div>
          {!updateMode ? (
            <button className="button-red" onClick={addNewDeal}>
              Add Deal
            </button>
          ) : (
            <button className="button-red" onClick={updateDeal}>
              Update Deal
            </button>
          )}
        </div>

        <div className="add_new_deal__content__all_product">
          <h4 className="add_new_deal__content__all_product__heading page_subheading">
            {dealType == "Single"
              ? "Add Product to the deal"
              : "Add Combo to the deal"}
          </h4>

          <div className="add_new_deal__content__all_product__search_container">
            <div className="transparent__input add_new_deal__content__all_product__search_container__search">
              <input type="text" placeholder="Search" />
              <SearchIcon className="transparent__input__icon" />
            </div>

            <div className="add_new_deal__content__all_product__search_container__category">
              <FormControl fullWidth>
                <Select value={categoryFilter} onChange={handleCategoryChange}>
                  <MenuItem value={"category"}>Category</MenuItem>
                </Select>
              </FormControl>
            </div>
            <div className="add_new_deal__content__all_product__search_container__sub_category">
              <FormControl fullWidth>
                <Select
                  value={subCategoryFilter}
                  onChange={handleSubCategoryChange}
                >
                  <MenuItem value={"sub_category"}>Sub Category</MenuItem>
                </Select>
              </FormControl>
            </div>
          </div>

          <div className="add_new_deal__content__all_product__content">
            <table className="deals__content__card_container__table__table">
              <tr>
                {dealType == "Single"
                  ? addedProductHeader?.map((header, index) => {
                      return (
                        <th key={index}>
                          <span>
                            {header?.name} <ArrowDropDownIcon />
                          </span>
                        </th>
                      );
                    })
                  : addedComboHeader?.map((header, index) => {
                      return (
                        <th key={index}>
                          <span>
                            {header?.name} <ArrowDropDownIcon />
                          </span>
                        </th>
                      );
                    })}
              </tr>
              {dealType == "Single"
                ? allProductList?.map((data, index) => {
                    return (
                      <tr key={index}>
                        <td>
                          <div className="product div-flex">
                            <img src={data?.images[0]} alt="Product Image" />
                            <div className="product__info">
                              <span>{data?.name}</span>
                              <span>
                                Details:{" "}
                                {data?.details?.length > 0
                                  ? data?.details[0]?.body
                                  : ""}
                              </span>
                            </div>
                          </div>
                        </td>
                        <td>&#8377; {data?.varients[0]?.sellingPrice}</td>
                        {/* <td>{data?.purchased}</td>
                        <td>{data?.stock}</td> */}
                        <td>
                          {new Date(data?.createdAt)?.toLocaleString("en-US", {
                            weekday: "short",
                            year: "numeric",
                            month: "short",
                            day: "numeric",
                            timeZone: "UTC",
                          })}
                        </td>
                        <td>
                          <div className="product_action">
                            <button
                              className="button-red"
                              onClick={() => {
                                const updatedArray = allProductList?.filter(
                                  (item) => item.id !== data?.id
                                );
                                setAllProductList(updatedArray);

                                setAddedProduct((prev) => {
                                  return [...prev, data];
                                });

                                setAddedProductIds((prev) => {
                                  return [...prev, data?.id];
                                });
                              }}
                            >
                              Add
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })
                : allComboList?.map((data, index) => {
                    return (
                      <tr key={index}>
                        <td>
                          <div className="product div-flex">
                            <img src={data?.image} alt="Product Image" />
                          </div>
                        </td>
                        <td>&#8377; {data?.name}</td>
                        {/* <td>{data?.purchased}</td>
                        <td>{data?.stock}</td> */}
                        <td>
                          {new Date(data?.createdAt)?.toLocaleString("en-US", {
                            weekday: "short",
                            year: "numeric",
                            month: "short",
                            day: "numeric",
                            timeZone: "UTC",
                          })}
                        </td>
                        <td>
                          <div className="product_action">
                            <button
                              className="button-red"
                              onClick={() => {
                                const updatedArray = allComboList?.filter(
                                  (item) => item.id !== data?.id
                                );
                                setAllComboList(updatedArray);

                                setAddedProduct((prev) => {
                                  return [...prev, data];
                                });

                                setAddedProductIds((prev) => {
                                  return [...prev, data?.id];
                                });
                              }}
                            >
                              Add
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
